fn parse_button(value: &str) -> Option<EnigoButton> {
    match value.trim().to_ascii_uppercase().as_str() {
        "LEFT_MOUSE" | "LEFT" | "BUTTON1" => Some(EnigoButton::Left),
        "RIGHT_MOUSE" | "RIGHT" | "BUTTON2" => Some(EnigoButton::Right),
        "MIDDLE_MOUSE" | "MIDDLE" | "BUTTON3" => Some(EnigoButton::Middle),
        "SIDE1" | "BACK" | "BACK_BUTTON" | "BUTTON4" => Some(EnigoButton::Back),
        "SIDE2" | "FORWARD" | "FORWARD_BUTTON" | "BUTTON5" => Some(EnigoButton::Forward),
        "SCROLL_UP" | "SCROLLUP" | "WHEEL_UP" => Some(EnigoButton::ScrollUp),
        "SCROLL_DOWN" | "SCROLLDOWN" | "WHEEL_DOWN" => Some(EnigoButton::ScrollDown),
        "SCROLL_LEFT" | "SCROLLLEFT" | "WHEEL_LEFT" => Some(EnigoButton::ScrollLeft),
        "SCROLL_RIGHT" | "SCROLLRIGHT" | "WHEEL_RIGHT" => Some(EnigoButton::ScrollRight),
        _ => None,
    }
}

fn start_click_thread(config: ClickConfig) -> Option<Arc<AtomicBool>> {
    let trigger = parse_key(&config.input);

    let input_lower = config.input.to_lowercase();
    if trigger.is_none() && input_lower != "side1" && input_lower != "side2" {
        eprintln!(
            "Warning: Unsupported keyboard input key '{}'; defaulting listener fallback to F6",
            config.input
        );
    }

    let output_button = match parse_button(&config.output) {
        Some(button) => button,
        None => {
            eprintln!(
                "Unsupported output button '{}'; defaulting to Left",
                config.output
            );
            EnigoButton::Left
        }
    };
    let global_running = Arc::new(AtomicBool::new(true));

    let click_enabled = Arc::new(AtomicBool::new(false));

    let click_enabled_loop = Arc::clone(&click_enabled);
    let click_enabled_listener = Arc::clone(&click_enabled);
    let global_running_loop = Arc::clone(&global_running);
    let global_running_listener = Arc::clone(&global_running);

    thread::spawn(move || {
        let mut enigo = Enigo::new(&Settings::default()).expect("failed to create Enigo instance");

        enigo.set_delay(0);

        let calibration_iterations = 20;
        let start_time = std::time::Instant::now();

        for _ in 0..calibration_iterations {
            let _ = enigo.button(output_button, Direction::Release);
        }

        let total_elapsed = start_time.elapsed().as_micros() as u64;
        let detected_overhead_us = total_elapsed / calibration_iterations;

        let device_overhead_us = detected_overhead_us.clamp(50, 500);
        println!(
            "SharpClicks: Calibrated device input overhead to {}µs",
            device_overhead_us
        );

        let spin_sleeper = spin_sleep::SpinSleeper::new(200_000)
            .with_spin_strategy(spin_sleep::SpinStrategy::SpinLoopHint);

        while global_running_loop.load(Ordering::SeqCst) {
            if click_enabled_loop.load(Ordering::SeqCst) {
                let timing = click_timing_from_cps_cdc(config.cps, config.cdc, device_overhead_us);

                enigo.button(output_button, Direction::Press).ok();
                spin_sleeper.sleep(Duration::from_micros(timing.hold_us));

                enigo.button(output_button, Direction::Release).ok();
                spin_sleeper.sleep(Duration::from_micros(timing.release_us));
            } else {
                spin_sleeper.sleep(Duration::from_millis(10));
            }
        }
    });

    thread::spawn(move || {
        use std::io::Write;

        println!("SharpClicks: Initializing global OS event hook...");
        let _ = std::io::stdout().flush();

        if let Err(err) = rdev::listen(move |event: rdev::Event| {
            if !global_running_listener.load(Ordering::SeqCst) {
                return;
            }

            if let EventType::MouseMove { .. } = event.event_type {
                return;
            }

            let is_trigger_active = match &event.event_type {
                EventType::KeyPress(key) => parse_key(&config.input).map_or(false, |k| k == *key),
                EventType::ButtonPress(button) => {
                    println!("SharpClicks Debug -> Pressed: {:?}", button);
                    let _ = std::io::stdout().flush();

                    match button {
                        rdev::Button::Unknown(8) => config.input.to_lowercase() == "side1",
                        rdev::Button::Unknown(9) => config.input.to_lowercase() == "side2",
                        rdev::Button::Left => config.input.to_ascii_uppercase() == "LEFT_MOUSE",
                        rdev::Button::Right => config.input.to_ascii_uppercase() == "RIGHT_MOUSE",
                        rdev::Button::Middle => config.input.to_ascii_uppercase() == "MIDDLE_MOUSE",
                        _ => false,
                    }
                }
                _ => false,
            };

            let is_trigger_released = match &event.event_type {
                EventType::KeyRelease(key) => parse_key(&config.input).map_or(false, |k| k == *key),
                EventType::ButtonRelease(button) => match button {
                    rdev::Button::Unknown(8) => config.input.to_lowercase() == "side1",
                    rdev::Button::Unknown(9) => config.input.to_lowercase() == "side2",
                    rdev::Button::Left => config.input.to_ascii_uppercase() == "LEFT_MOUSE",
                    rdev::Button::Right => config.input.to_ascii_uppercase() == "RIGHT_MOUSE",
                    rdev::Button::Middle => config.input.to_ascii_uppercase() == "MIDDLE_MOUSE",
                    _ => false,
                },
                _ => false,
            };

            if is_trigger_active {
                if config.click_mode == 1 {
                    let next = !click_enabled_listener.load(Ordering::SeqCst);
                    click_enabled_listener.store(next, Ordering::SeqCst);
                } else {
                    click_enabled_listener.store(true, Ordering::SeqCst);
                }
            } else if is_trigger_released {
                if config.click_mode == 0 {
                    click_enabled_listener.store(false, Ordering::SeqCst);
                }
            }
        }) {
            eprintln!("CRITICAL ERROR: Failed to attach global system hook: {err:?}");
        }
    });

    Some(global_running)
}
